Console.WriteLine($"Age 8:  {Pricing.Category(8)}, {Pricing.TicketPrice(8, false):F2}");
Console.WriteLine($"Age 30: {Pricing.Category(30)}, {Pricing.TicketPrice(30, false):F2}");
Console.WriteLine($"Age 70: {Pricing.Category(70)}, {Pricing.TicketPrice(70, false):F2}");
Console.WriteLine($"Age 2 on a Saturday: {Pricing.TicketPrice(2, true):F2}");
Console.WriteLine($"Age 8 on a Saturday: {Pricing.TicketPrice(8, true):F2}");

static class Pricing
{
    // "free" under 3, "child" from 3 to 12, "senior" at 65 and over, "adult" otherwise.
    // Use a switch expression.
    public static string Category(int age)
    {
        return age switch
        {
            < 3 => "free",
            <= 12 => "child",
            >= 65 => "senior",
            _ => "adult",
        };
    }

    // free: 0.00, child: 8.50, adult: 12.50, senior: 9.00.
    // Weekends add 2.00 to every ticket that isn't free.
    public static decimal TicketPrice(int age, bool isWeekend)
    {
        decimal price = Category(age) switch
        {
            "free" => 0m,
            "child" => 8.50m,
            "senior" => 9.00m,
            _ => 12.50m,
        };
        if (isWeekend && price > 0m)
            price = price + 2.00m;
        return price;
    }
}

hints.markdown:
`Category` can start like this:

```csharp
return age switch
{
    < 3 => "free",
    <= 12 => "child",
    // senior, then _ for adult
};
```

In `TicketPrice`, get the base price with a switch on `Category(age)`, then add the extra with `if (isWeekend && price > 0m)`.

