// Gradebook. This prints a report; the calculations live in the Stats class below.
List<int> scores = [72, 95, 58, 88, 64, 100, 49];

Console.WriteLine($"Scores: {string.Join(", ", scores)}");
Console.WriteLine($"Average: {Stats.Average(scores):F1}");
Console.WriteLine($"Passing (60+): {Stats.CountPassing(scores, 60)}");
Console.WriteLine($"Curved by 5: {string.Join(", ", Stats.Curved(scores, 5))}");

static class Stats
{
    // The mean of the scores, with the fraction kept. An empty list has an average of 0.
    // This one has bugs: run the program and read the Output.
    public static double Average(List<int> scores)
    {
        if (scores.Count == 0)
            return 0;
        int total = 0;
        for (int i = 0; i < scores.Count; i++)
            total += scores[i];
        return (double)total / scores.Count;
    }

    // How many scores are at or above passMark.
    public static int CountPassing(List<int> scores, int passMark)
    {
        int count = 0;
        foreach (int score in scores)
        {
            if (score >= passMark)
                count++;
        }
        return count;
    }

    // A NEW list: each score plus the bonus, but never more than 100.
    // Don't change the list that was passed in.
    public static List<int> Curved(List<int> scores, int bonus)
    {
        var curved = new List<int>();
        foreach (int score in scores)
            curved.Add(Math.Min(score + bonus, 100));
        return curved;
    }
}

hints.markdown:
`Curved` builds a new list:

```csharp
var curved = new List<int>();
foreach (int score in scores)
    curved.Add(Math.Min(score + bonus, 100));
return curved;
```

`CountPassing` has the same shape: a counter that goes up when `score >= passMark`.

