static class Text
{
    public static string Initials(string fullName)
    {
        string result = "";
        foreach (string part in fullName.Split(' '))
            result += part[0];
        return result;
    }

    // count and separator are optional.
    public static string Repeat(string text, int count = 3, string separator = "")
    {
        var parts = new List<string>();
        for (int i = 0; i < count; i++)
            parts.Add(text);
        return string.Join(separator, parts);
    }

    // Overloads: same name, different parameter types.
    public static string Describe(int n) => $"the number {n}";
    public static string Describe(string s) => $"the text \"{s}\"";

    // Not pure: it changes the list it was given.
    public static void AddGrace(List<string> list) => list.Add("Grace");
}

