// Recipe scaler. The code below calls three methods that don't exist yet: write them in the Kitchen class.
string request = "6";

if (Kitchen.TryParseServings(request, out int servings))
{
    Console.WriteLine($"Pancakes for {servings}:");
    Console.WriteLine($"Flour: {Kitchen.Format(Kitchen.Scale(200, servings))}");
    Console.WriteLine($"Milk: {Kitchen.Format(Kitchen.Scale(300, servings))}");
    Console.WriteLine($"Butter: {Kitchen.Format(Kitchen.Scale(50, servings, 2))}");
}
else
{
    Console.WriteLine($"\"{request}\" isn't a number of servings from 1 to 20.");
}

static class Kitchen
{
    // 1. Scale returns amount * toServings / fromServings, as a double.
    //    fromServings is optional, because most recipes are written for 4:
    //    Kitchen.Scale(200, 6) is 300, and Kitchen.Scale(50, 6, 2) is 150.
    public static double Scale(double amount, int toServings, int fromServings = 4)
    {
        return amount * toServings / fromServings;
    }

    // 2. Format takes grams (a double). Under 1000, it returns whole grams, like "300 g".
    //    From 1000 up, it returns kilograms with one decimal place, like "1.5 kg".
    public static string Format(double grams)
    {
        if (grams < 1000)
            return $"{grams:0} g";
        return $"{grams / 1000:0.0} kg";
    }

    // 3. TryParseServings(string text, out int servings) works like int.TryParse,
    //    but only whole numbers from 1 to 20 count. It returns true and sets servings
    //    for those; otherwise it returns false and sets servings to 0.
    public static bool TryParseServings(string text, out int servings)
    {
        if (int.TryParse(text, out servings) && servings >= 1 && servings <= 20)
            return true;
        servings = 0;
        return false;
    }
}

