// This bank account has no rules: any code can change its balance, and it can be overdrawn.
// Give it rules. Then the code below should print the two lines in the instructions.
var account = new BankAccount("Ada", 20m);
account.Deposit(15.50m);
bool ok = account.Withdraw(100m);
Console.WriteLine($"Withdraw 100: {(ok ? "done" : "declined")}");
Console.WriteLine(account.Summary());

class BankAccount
{
    public string Owner { get; }
    public decimal Balance { get; private set; }

    public BankAccount(string owner, decimal openingBalance = 0)
    {
        if (openingBalance < 0)
            throw new ArgumentException("The opening balance can't be negative.");
        Owner = owner;
        Balance = openingBalance;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentException("Deposit a positive amount.");
        Balance += amount;
    }

    public bool Withdraw(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentException("Withdraw a positive amount.");
        if (amount > Balance)
            return false;
        Balance -= amount;
        return true;
    }

    public string Summary()
    {
        return $"{Owner}: {Balance:F2}";
    }
}

